const dialogs = h.$$('[role="dialog"][aria-label="Try the new HardMail"]');
for (const d of dialogs) {
  const btn = h.$('[role="button"][aria-label="Not now"]', d);
  if (btn && h.visible(btn)) { h.click(btn); await h.sleep(200); }
}
if (h.findByText(/^Reply$/)) return state;
const row = h.$$('tr[role="row"]', h.$('table[role="grid"][aria-label="Inbox"]')).find(r => /Q4 launch checklist/.test(r.textContent));
if (!row) throw new Error('Row "Q4 launch checklist" not found in Inbox grid');
const target = h.$('span.bog', row) || h.$('td.y2', row) || row;
h.click(target);
let opened = await h.waitFor(() => h.findByText(/^Reply$/), 2500);
if (!opened) {
  const cell = h.$('td.y2', row) || row;
  for (const t of ['mousedown','mouseup','click','dblclick']) {
    cell.dispatchEvent(new MouseEvent(t, {bubbles: true, cancelable: true, view: window}));
  }
  opened = await h.waitFor(() => h.findByText(/^Reply$/), 4000);
}
if (!opened) throw new Error('Message view did not open: no Reply control found after clicking the row');
return state;

