const findEditor = () => h.$$('textarea, [contenteditable="true"], [contenteditable=""], [contenteditable="plaintext-only"], [role="textbox"]').find(e => h.visible(e) && !e.disabled && !e.readOnly);
if (findEditor()) return state;
const findStub = () => h.$('[aria-label="Expand composer"]') || h.$$('[role="button"][aria-expanded="false"]').find(e => /expand|composer/i.test(h.label(e) || e.textContent || '')) || h.findByText(/expand composer|click to expand/i);
let stub = findStub();
if (!stub) {
  const ctrl = h.$('[aria-label="Respond"]') || h.$('[aria-label="Reply"]') || h.findByText(/^\s*(Respond|Reply)\s*$/i);
  if (!ctrl) throw new Error('No Respond/Reply control and no collapsed composer stub found in the open message view');
  h.click(ctrl);
  const got = await h.waitFor(() => findEditor() || findStub(), 6000);
  if (got && findEditor()) return state;
  stub = findStub();
}
if (!stub) throw new Error('Respond was clicked but neither an editable composer nor an expand control appeared');
for (let i = 0; i < 3; i++) {
  h.click(stub);
  const ed = await h.waitFor(findEditor, 4000);
  if (ed) { try { ed.focus(); } catch (e) {} return state; }
  const again = findStub();
  if (again) stub = again;
  await h.sleep(300);
}
